#!/usr/bin/env bash
set -euo pipefail
cd "$HOME/PFMP" || exit 1

DEPLOYMENT_ID="AKfycby6ykCxTxhUjq8FeKoBzgEMj6xzdrjXnBFgOt-1pAw1GfkaAigWMH7jj0EIg_BWpEkmxg"
LABEL="PFMP v1.0.0-dev.154"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="backup_avant_DEV154_${STAMP}"
mkdir -p "$BACKUP"

for f in apps-script/EUC_SUIVI_PFMP_ClassesV154.gs apps-script/Suivi_PFMP_Classes.html apps-script/EDT.js apps-script/Admin_PFMP.html apps-script/Admin_Conventions_PFMP.html; do
  [ -f "$f" ] && cp "$f" "$BACKUP/" || true
done

echo "" | base64 -d > apps-script/EUC_SUIVI_PFMP_ClassesV154.gs
echo "" | base64 -d > apps-script/Suivi_PFMP_Classes.html

cat > /tmp/dev154_tile.html <<EOF
<section class="card" id="suivi-pfmp-classes-v154">
  <h2>Suivi des PFMP par classe</h2>
  <p>Tableaux de suivi par année scolaire, classe et période, avec compteurs de conventions enregistrées.</p>
  <a class="btn primary" href="https://script.google.com/macros/s/$DEPLOYMENT_ID/exec?page=suivi-pfmp-classes">Ouvrir le suivi par classe</a>
</section>
EOF

echo "" | base64 -d > /tmp/dev154_router.py
echo "" | base64 -d > /tmp/dev154_admin.py
echo "" | base64 -d > /tmp/dev154_conv.py

python3 /tmp/dev154_router.py
python3 /tmp/dev154_admin.py
python3 /tmp/dev154_conv.py

echo "=== CONTROLES DEV.154 ==="
node --check /tmp/dev154_dummy.js 2>/dev/null || true
cp apps-script/EUC_SUIVI_PFMP_ClassesV154.gs /tmp/EUC_SUIVI_PFMP_ClassesV154.js
node --check /tmp/EUC_SUIVI_PFMP_ClassesV154.js
cp apps-script/EDT.js /tmp/EDT_DEV154.js
node --check /tmp/EDT_DEV154.js
grep -q "EUC_SUIVI_CLASSES_accueilV154" apps-script/EUC_SUIVI_PFMP_ClassesV154.gs
grep -q "page === 'suivi-pfmp-classes'" apps-script/EDT.js
grep -q 'id="suivi-pfmp-classes-v154"' apps-script/Admin_PFMP.html
grep -q "DEV154_markHistoryRed" apps-script/Admin_Conventions_PFMP.html

echo "=== PUSH ==="
clasp push -f
echo "=== VERSION ==="
clasp version "$LABEL"
echo "=== DEPLOIEMENT PRINCIPAL ==="
clasp deploy -i "$DEPLOYMENT_ID" -d "$LABEL"

echo "============================================================"
echo " DEV.154 DEPLOYEE AVEC SUCCES"
echo "============================================================"
echo "✓ correction/suppression mises en évidence en rouge"
echo "✓ vignette Suivi des PFMP par classe"
echo "✓ filtre année scolaire central dès l'entrée"
echo "✓ groupes BAC PRO / BTS / CAP"
echo "✓ effectif réel par classe"
echo "✓ compteur par période : conventions / effectif"
echo "✓ DEV.155 annoncé pour le tableau détaillé"
echo
echo "Diagnostic disponible dans Apps Script :"
echo "DIAGNOSTIC_DEV154_ACCUEIL"
echo "============================================================"
